mintedAmount[msg.sender] += realcost;

if (feeTo != address(0)) {
payable(feeTo).transfer(realcost);
}

uint256 refund = msg.value - realcost;
if (refund > 0) {
payable(msg.sender).transfer(refund);
}
}

